action.mutation:
mutation CreateScheduleRequirement($payload: [ScheduleRequirementCreatePayloadInput!]!) {
        mutation: createScheduleRequirement(payload: $payload) { 
          id
          id
      }
    }

mutation UpdateScheduleRequirement($payload: [ScheduleRequirementUpdatePayloadInput!]!) {
        mutation: updateScheduleRequirement(payload: $payload) { 
          id
          id
      }
    }

mutation DeleteScheduleRequirement($payload: [ScheduleRequirementDeletePayloadInput!]!) {
        mutation: deleteScheduleRequirement(payload: $payload) { 
          id
          id
      }
    }
